#include <vector>
#include <string>

class Solution {
public:
    std::vector<int> platesBetweenCandles(std::string s, std::vector<std::vector<int>>& queries) {
        int n = s.size();
        std::vector<int> platesPref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            platesPref[i + 1] = platesPref[i] + (s[i] == '*' ? 1 : 0);
        }

        std::vector<int> leftCandle(n, -1);
        int last = -1;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '|') last = i;
            leftCandle[i] = last;
        }

        std::vector<int> rightCandle(n, -1);
        last = -1;
        for (int i = n - 1; i >= 0; --i) {
            if (s[i] == '|') last = i;
            rightCandle[i] = last;
        }

        std::vector<int> res;
        res.reserve(queries.size());
        for (const auto& q : queries) {
            int c1 = rightCandle[q[0]];
            int c2 = leftCandle[q[1]];
            if (c1 != -1 && c2 != -1 && c1 < c2) {
                res.push_back(platesPref[c2 + 1] - platesPref[c1]);
            } else {
                res.push_back(0);
            }
        }
        return res;
    }
};

import java.util.Arrays;

class Solution {
    public int[] platesBetweenCandles(String s, int[][] queries) {
        int n = s.length();
        int[] platesPref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            platesPref[i + 1] = platesPref[i] + (s.charAt(i) == '*' ? 1 : 0);
        }

        int[] leftCandle = new int[n];
        int last = -1;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '|') last = i;
            leftCandle[i] = last;
        }

        int[] rightCandle = new int[n];
        last = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == '|') last = i;
            rightCandle[i] = last;
        }

        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int c1 = rightCandle[queries[i][0]];
            int c2 = leftCandle[queries[i][1]];
            if (c1 != -1 && c2 != -1 && c1 < c2) {
                res[i] = platesPref[c2 + 1] - platesPref[c1];
            } else {
                res[i] = 0;
            }
        }
        return res;
    }
}

