var platesBetweenCandles = function(s, queries) {
    const n = s.length;
    const platesPref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        platesPref[i + 1] = platesPref[i] + (s[i] === '*' ? 1 : 0);
    }

    const leftCandle = new Array(n).fill(-1);
    let last = -1;
    for (let i = 0; i < n; i++) {
        if (s[i] === '|') last = i;
        leftCandle[i] = last;
    }

    const rightCandle = new Array(n).fill(-1);
    last = -1;
    for (let i = n - 1; i >= 0; i--) {
        if (s[i] === '|') last = i;
        rightCandle[i] = last;
    }

    const res = [];
    for (const [l, r] of queries) {
        const c1 = rightCandle[l];
        const c2 = leftCandle[r];
        if (c1 !== -1 && c2 !== -1 && c1 < c2) {
            res.push(platesPref[c2 + 1] - platesPref[c1]);
        } else {
            res.push(0);
        }
    }
    return res;
};
